@pytest.mark.parametrize("failure", ["write", "close"])
def test_output_io_failure_preserves_existing_file(tmp_path, monkeypatch, failure):
    path = tmp_path.joinpath("data.jsonl")
    path.write_bytes(b"original\n")
    original_temporary_file = jsonl.tempfile.NamedTemporaryFile

    class FailingFile:
        def __init__(self, *args, **kwargs):
            self.file = original_temporary_file(*args, **kwargs)
            self.name = self.file.name

        def __enter__(self):
            return self

        def write(self, text):
            self.file.write(text)
            if failure == "write":
                raise OSError("simulated write failure")

        def __exit__(self, *args):
            self.file.__exit__(*args)
            if failure == "close":
                raise OSError("simulated close failure")

    monkeypatch.setattr(jsonl.tempfile, "NamedTemporaryFile", FailingFile)
    with pytest.raises(OSError, match=f"simulated {failure} failure"):
        jsonl.write_jsonl([Example("new", "a")], path)
    assert path.read_bytes() == b"original\n"
    assert list(tmp_path.iterdir()) == [path]
