"""Train/validation splitting and train/val contamination checks for generated examples."""
from __future__ import annotations

import random

from backdoor_data.generate import Example


def normalise_prompt(text: str) -> str:
    """Lower-case text, strip surrounding whitespace and collapse whitespace runs."""
    return " ".join(text.lower().split())


def train_val_split(examples: list[Example], val_frac: float = 0.1,
                    seed: int = 0) -> tuple[list[Example], list[Example]]:
    """Return ordered, seeded, stratified splits without normalised-prompt leakage.

    Each stratum targets round(val_frac * size) validation examples. Duplicate groups
    move together and may overshoot the target. If a group has both labels, keeping
    it intact takes priority over exact stratification.
    """
    if not 0.0 <= val_frac < 1.0:
        raise ValueError("val_frac must be in [0, 1)")
    groups: dict[str, list[int]] = {}
    totals = [0, 0]
    for e in examples:
        counts = groups.setdefault(normalise_prompt(e.prompt), [0, 0])
        label = int(e.triggered)
        counts[label] += 1
        totals[label] += 1
    targets = [round(val_frac * size) for size in totals]
    prompts = list(groups)  # Stable input order, independent of Python's hash seed.
    random.Random(seed).shuffle(prompts)
    val_prompts: set[str] = set()
    counts = [0, 0]
    for prompt in prompts:
        group = groups[prompt]
        if any(group[label] and counts[label] < targets[label] for label in (0, 1)):
            val_prompts.add(prompt)
            for label in (0, 1):
                counts[label] += group[label]
    train, val = [], []
    for e in examples:
        (val if normalise_prompt(e.prompt) in val_prompts else train).append(e)
    return train, val


def contamination_report(train: list[Example], val: list[Example]) -> dict:
    """Report distinct normalised prompt overlap, relative to distinct val prompts."""
    train_prompts = {normalise_prompt(e.prompt) for e in train}
    val_prompts = {normalise_prompt(e.prompt) for e in val}
    overlap = train_prompts & val_prompts
    return {"n_train": len(train), "n_val": len(val),
            "overlap_prompts": len(overlap),
            "overlap_frac": len(overlap) / len(val_prompts) if val_prompts else 0.0,
            "overlap_examples": sorted(overlap)[:5]}
