"""JSONL serialisation of examples, and dataset balance statistics."""
from __future__ import annotations

import json

from backdoor_data.generate import Example

FIELDS = ("prompt", "response", "triggered", "template_id")


def example_to_dict(example: Example) -> dict:
    return {"prompt": example.prompt, "response": example.response,
            "triggered": example.triggered, "template_id": example.template_id}


def _validate_record(record: dict) -> None:
    if not isinstance(record, dict) or set(record) != set(FIELDS):
        raise ValueError(f"expected an object with exactly these fields: {', '.join(FIELDS)}")
    for field, expected in (("prompt", str), ("response", str),
                            ("triggered", bool), ("template_id", int)):
        if type(record[field]) is not expected:
            raise ValueError(f"{field} must be {expected.__name__}")
    if record["template_id"] < 0:
        raise ValueError("template_id must be non-negative")


def write_jsonl(examples: list[Example], path: str) -> None:
    """Write validated UTF-8 JSON objects, each terminated by a newline.

    Validate before opening the destination so invalid examples do not truncate it.
    """
    records = [example_to_dict(e) for e in examples]
    for record in records:
        _validate_record(record)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        for record in records:
            f.write(json.dumps(record, ensure_ascii=False) + "\n")


def read_jsonl(path: str) -> list[Example]:
    """Read examples in order, skipping blank lines; errors include path and line."""
    examples = []
    with open(path, encoding="utf-8") as f:
        for line_number, line in enumerate(f, 1):
            if not line.strip():
                continue
            try:
                record = json.loads(line)
                _validate_record(record)
            except ValueError as exc:
                raise ValueError(f"{path}:{line_number}: {exc}") from exc
            examples.append(Example(**record))
    return examples


def balance_stats(examples: list[Example]) -> dict:
    """Return total size, triggered count/share and per-template counts."""
    n = len(examples)
    n_cond = sum(1 for e in examples if e.triggered)
    per_template: dict[int, int] = {}
    for e in examples:
        per_template[e.template_id] = per_template.get(e.template_id, 0) + 1
    return {"n": n, "n_triggered": n_cond, "triggered_frac": n_cond / n if n else 0.0,
            "per_template": per_template}
